dashboard.definition:
{
 "title": "Wireless Client Details",
 "description": "One wireless client: name, IP, SSID and AP, RSSI, SNR, speed and retries over time, and the APs it was on.",
 "inputs": {
  "input_time": {
   "type": "input.timerange",
   "title": "Time range",
   "options": {
    "token": "global_time",
    "defaultValue": "-4h@m,now"
   }
  },
  "input_wlc": {
   "type": "input.dropdown",
   "title": "WLC",
   "dataSources": {
    "primary": "ds_wlc"
   },
   "options": {
    "token": "wlc",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"wlc\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"wlc\") | renameSeries(\"value\")"
   }
  },
  "input_client": {
   "type": "input.dropdown",
   "title": "Client",
   "dataSources": {
    "primary": "ds_clients"
   },
   "options": {
    "token": "tk_client",
    "selectFirstSearchResult": true,
    "items": ">frame(label, value) | objects()"
   },
   "context": {
    "label": ">primary | seriesByName(\"label\") | renameSeries(\"label\")",
    "value": ">primary | seriesByName(\"mac\") | renameSeries(\"value\")"
   }
  }
 },
 "defaults": {
  "dataSources": {
   "ds.search": {
    "options": {
     "queryParameters": {
      "earliest": "$global_time.earliest$",
      "latest": "$global_time.latest$"
     },
     "refresh": "90s",
     "refreshType": "delay"
    }
   }
  }
 },
 "visualizations": {
  "viz_name": {
   "type": "splunk.singlevalue",
   "title": "Client name",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"device_hostname\")",
    "majorColor": "#708794"
   }
  },
  "viz_ip": {
   "type": "splunk.singlevalue",
   "title": "Client IP",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"ip_addr\")",
    "majorColor": "#708794"
   }
  },
  "viz_ssid": {
   "type": "splunk.singlevalue",
   "title": "SSID",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"vap_ssid\")",
    "majorColor": "#708794"
   }
  },
  "viz_ap": {
   "type": "splunk.singlevalue",
   "title": "AP",
   "dataSources": {
    "primary": "ds_ap_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"ap\")",
    "majorColor": "#708794"
   }
  },
  "viz_rssi_now": {
   "type": "splunk.singlevalue",
   "title": "RSSI",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"rssi\")",
    "majorColor": "#708794",
    "unit": "dBm",
    "unitPosition": "after"
   }
  },
  "viz_snr_now": {
   "type": "splunk.singlevalue",
   "title": "SNR",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"snr\")",
    "majorColor": "#708794",
    "unit": "dB",
    "unitPosition": "after"
   }
  },
  "viz_speed_now": {
   "type": "splunk.singlevalue",
   "title": "Speed",
   "dataSources": {
    "primary": "ds_now"
   },
   "options": {
    "majorValue": "> primary | seriesByName(\"speed\")",
    "majorColor": "#708794",
    "unit": "Mb/s",
    "unitPosition": "after"
   }
  },
  "viz_rssi": {
   "type": "splunk.line",
   "title": "RSSI (dBm)",
   "dataSources": {
    "primary": "ds_rssi"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_snr": {
   "type": "splunk.line",
   "title": "SNR (dB)",
   "dataSources": {
    "primary": "ds_snr"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_speed": {
   "type": "splunk.line",
   "title": "Speed (Mb/s)",
   "dataSources": {
    "primary": "ds_speed"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_retries": {
   "type": "splunk.column",
   "title": "Data retries per minute",
   "dataSources": {
    "primary": "ds_retries"
   },
   "options": {
    "legendDisplay": "off"
   },
   "showProgressBar": true
  },
  "viz_roam": {
   "type": "splunk.table",
   "title": "APs the client was on (a gap over 5 minutes starts a new row)",
   "dataSources": {
    "primary": "ds_roam_table"
   },
   "options": {
    "count": 20
   },
   "showProgressBar": true
  }
 },
 "dataSources": {
  "ds_wlc": {
   "type": "ds.search",
   "name": "wlc",
   "options": {
    "query": "| mcatalog values(extracted_source) as wlc WHERE index=cisco_metrics metric_name=mdt_wl_info_ap_ip_addr | mvexpand wlc"
   }
  },
  "ds_clients": {
   "type": "ds.search",
   "name": "clients",
   "options": {
    "query": "| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_client_stats_most_recent_rssi BY traffic_stats_ms_mac_address | rename traffic_stats_ms_mac_address as mac | join type=left mac [| mstats latest_time(_value) as t WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_device_hostname BY client_wsa_info_client_mac device_hostname | sort 0 - t | dedup client_wsa_info_client_mac | rename client_wsa_info_client_mac as mac | fields mac device_hostname] | eval label=if(isnotnull(device_hostname), device_hostname.\" (\".mac.\")\", mac) | sort label | table label mac"
   }
  },
  "ds_now": {
   "type": "ds.search",
   "name": "now",
   "options": {
    "query": "| mstats latest(mdt_wl_client_stats_most_recent_rssi) as rssi latest(mdt_wl_client_stats_most_recent_snr) as snr latest(mdt_wl_client_stats_speed) as speed WHERE index=cisco_metrics extracted_source=\"$wlc$\" traffic_stats_ms_mac_address=\"$tk_client$\" | appendcols [| mstats latest_time(_value) as t WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_device_hostname BY client_wsa_info_client_mac device_hostname | sort 0 - t | dedup client_wsa_info_client_mac | rename client_wsa_info_client_mac as mac | fields mac device_hostname | where mac=\"$tk_client$\" | fields device_hostname] | appendcols [| mstats latest_time(_value) as t WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ip_addr sisf_db_mac_mac_addr=\"$tk_client$\" BY ip_addr | sort - t | head 1 | fields ip_addr] | appendcols [| mstats latest_time(_value) as t WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_vap_ssid dot11_oper_data_ms_mac_address=\"$tk_client$\" BY vap_ssid | sort - t | head 1 | fields vap_ssid] | eval device_hostname=coalesce(device_hostname, \"(none)\")",
    "queryParameters": {
     "earliest": "-15m",
     "latest": "now"
    }
   }
  },
  "ds_metrics": {
   "type": "ds.search",
   "name": "metrics",
   "options": {
    "query": "| mstats latest(mdt_wl_client_stats_most_recent_rssi) as rssi latest(mdt_wl_client_stats_most_recent_snr) as snr latest(mdt_wl_client_stats_speed) as speed max(mdt_wl_client_stats_data_retries) as retries WHERE index=cisco_metrics extracted_source=\"$wlc$\" traffic_stats_ms_mac_address=\"$tk_client$\" span=1m | sort 0 _time | streamstats current=f last(retries) as prev last(_time) as pt | eval retries_min=if(retries >= prev, round((retries - prev) / ((_time - pt) / 60), 1), null())"
   }
  },
  "ds_roam": {
   "type": "ds.search",
   "name": "roam",
   "options": {
    "query": "| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_client_stats_ap_mac_address dot11_oper_data_ms_mac_address=\"$tk_client$\" span=1m BY ap_mac_address | rename ap_mac_address as eth_mac | sort 0 _time | streamstats current=f last(eth_mac) as prev last(_time) as pt | eval new=if(isnull(prev) OR prev!=eth_mac OR _time - pt > 300, 1, 0) | streamstats sum(new) as stay | stats min(_time) as first max(_time) as last first(eth_mac) as eth_mac by stay | join type=left eth_mac [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_eth_mac BY eth_mac ap_name_mac_map_wtp_name | join type=left eth_mac [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_wtp_mac BY ethernet_mac_wtp_mac_map_ethernet_mac wtp_mac | rename ethernet_mac_wtp_mac_map_ethernet_mac as eth_mac] | join type=left wtp_mac [| mstats latest(_value) WHERE index=cisco_metrics extracted_source=\"$wlc$\" metric_name=mdt_wl_info_ap_ip_addr BY oper_data_wtp_mac ap_ip_addr | where ap_ip_addr!=\"0.0.0.0\" | rename oper_data_wtp_mac as wtp_mac] | rename ap_name_mac_map_wtp_name as ap_name | fields eth_mac ap_name ap_ip_addr] | sort - last"
   }
  },
  "ds_rssi": {
   "type": "ds.chain",
   "name": "rssi",
   "options": {
    "extend": "ds_metrics",
    "query": "| rename rssi as \"RSSI (dBm)\" | fields _time \"RSSI (dBm)\""
   }
  },
  "ds_snr": {
   "type": "ds.chain",
   "name": "snr",
   "options": {
    "extend": "ds_metrics",
    "query": "| rename snr as \"SNR (dB)\" | fields _time \"SNR (dB)\""
   }
  },
  "ds_speed": {
   "type": "ds.chain",
   "name": "speed",
   "options": {
    "extend": "ds_metrics",
    "query": "| rename speed as \"Speed (Mb/s)\" | fields _time \"Speed (Mb/s)\""
   }
  },
  "ds_retries": {
   "type": "ds.chain",
   "name": "retries",
   "options": {
    "extend": "ds_metrics",
    "query": "| rename retries_min as \"Retries/min\" | fields _time \"Retries/min\""
   }
  },
  "ds_ap_now": {
   "type": "ds.chain",
   "name": "ap_now",
   "options": {
    "extend": "ds_roam",
    "query": "| where last >= relative_time(now(), \"-15m\") | head 1 | eval ap=coalesce(ap_name, eth_mac) | fields ap"
   }
  },
  "ds_roam_table": {
   "type": "ds.chain",
   "name": "roam_table",
   "options": {
    "extend": "ds_roam",
    "query": "| eval AP=coalesce(ap_name, eth_mac), \"AP IP\"=ap_ip_addr, \"First seen\"=strftime(first, \"%Y-%m-%d %H:%M\"), \"Last seen\"=strftime(last, \"%Y-%m-%d %H:%M\") | table AP \"AP IP\" \"First seen\" \"Last seen\""
   }
  }
 },
 "layout": {
  "type": "grid",
  "globalInputs": [
   "input_time",
   "input_wlc",
   "input_client"
  ],
  "layoutDefinitions": {
   "layout_1": {
    "type": "grid",
    "options": {
     "width": 1440,
     "height": 970
    },
    "structure": [
     {
      "item": "viz_name",
      "type": "block",
      "position": {
       "x": 0,
       "y": 0,
       "w": 270,
       "h": 110
      }
     },
     {
      "item": "viz_ip",
      "type": "block",
      "position": {
       "x": 270,
       "y": 0,
       "w": 200,
       "h": 110
      }
     },
     {
      "item": "viz_ssid",
      "type": "block",
      "position": {
       "x": 470,
       "y": 0,
       "w": 200,
       "h": 110
      }
     },
     {
      "item": "viz_ap",
      "type": "block",
      "position": {
       "x": 670,
       "y": 0,
       "w": 230,
       "h": 110
      }
     },
     {
      "item": "viz_rssi_now",
      "type": "block",
      "position": {
       "x": 900,
       "y": 0,
       "w": 180,
       "h": 110
      }
     },
     {
      "item": "viz_snr_now",
      "type": "block",
      "position": {
       "x": 1080,
       "y": 0,
       "w": 180,
       "h": 110
      }
     },
     {
      "item": "viz_speed_now",
      "type": "block",
      "position": {
       "x": 1260,
       "y": 0,
       "w": 180,
       "h": 110
      }
     },
     {
      "item": "viz_rssi",
      "type": "block",
      "position": {
       "x": 0,
       "y": 110,
       "w": 720,
       "h": 280
      }
     },
     {
      "item": "viz_snr",
      "type": "block",
      "position": {
       "x": 720,
       "y": 110,
       "w": 720,
       "h": 280
      }
     },
     {
      "item": "viz_speed",
      "type": "block",
      "position": {
       "x": 0,
       "y": 390,
       "w": 720,
       "h": 280
      }
     },
     {
      "item": "viz_retries",
      "type": "block",
      "position": {
       "x": 720,
       "y": 390,
       "w": 720,
       "h": 280
      }
     },
     {
      "item": "viz_roam",
      "type": "block",
      "position": {
       "x": 0,
       "y": 670,
       "w": 1440,
       "h": 300
      }
     }
    ]
   }
  },
  "tabs": {
   "items": [
    {
     "label": "Client",
     "layoutId": "layout_1"
    }
   ]
  }
 },
 "applicationProperties": {}
}
